ng_app=X/postgres","postgres=X/postgres"],"booking.suppress_guest_notification(p_intent uuid, p_by text)":["mv_booking_app=X/postgres","postgres=X/postgres"]},"columns":"15883a56df015cb58a8d023392c46ecf3785331106f7b15b649cd64fbfee76d8","constraints":"4926640ec4c48335c3efabde82f715aeade4d9e205731a72a6f19e9dec8b9bae","function_count":146,"functions":"50a50a7fbea38e8dd59ddd9f1094bcbd776fd465a2053f0430f0f1a4cb03ea84","indexes":"ec7528beb9cd888ce636a9b840cef8bfad746c919987c330462363dbea2e3c67","is_privileged_config":["search_path=pg_catalog, pg_temp"],"is_privileged_src":"a14a1dc5befcd96d03ca1c7e28020c5b07b6d1b212510cc1ad715368bc43fb9d","objects":{"claim_guest_notification_v2":true,"complete_guest_notification_resend":true,"notification_provider_receipt_binding":true,"notification_provider_receipts":true,"policy_receipts_app_admin_read":true,"renders_copy_contract_column":true,"renders_locale_column":true,"renders_version_binding":true,"trg_receipts_append_only":true,"trg_receipts_binding":true,"trg_receipts_no_truncate":true},"policies":"4c961469c87ff8cef1225e711236d82f2aa61f713ed02e4a6165b00be012e923","policy_count":74,"prerequisite_0021":{"claim_guest_notification_0016":true,"complete_guest_notification_0016":true,"guest_notification_presend":true,"notification_suppressions":true,"notify_op_fence":true,"recorded_state_cleanup_ok":true,"suppress_guest_notification":true},"relation_count":30,"relations":"a5c74de34cb9527bb6ad01fb7b75c5d18c352beae991778cb87fae64d4dfe810","rls":"b1f22dd33391daa40ad53ba5bada71bac08689965201b960928cd79b2bf605b3","rls_enabled_count":30,"schema_owner":"postgres","table_acls":"cae2965dab90a3acdae56bc5e5b6054f3d7db6cf91f512935f943940a65e5565","test_cleanup_pending_state":true,"trigger_count":85,"triggers":"9bf476e6ab78f75fba27d0c7485acb279d7a035e202703240d15d9c1de476375"}'::jsonb;
  inv jsonb; t_pre jsonb; t_post jsonb; h text; n bigint; mx int; k text; bad text := '';
  r12_pre text; ids_pre text; hrows_pre text;
BEGIN
  PERFORM set_config('lock_timeout', '5s', true);
  PERFORM pg_advisory_xact_lock(7302215001);                             -- = db/lib/migrate.js LOCK_KEY (transaction-scoped)
  IF encode(sha256(convert_to(up22, 'UTF8')), 'hex') <> c_up22 THEN RAISE EXCEPTION 'E7_23_UP22_BYTES_MISMATCH'; END IF;
  IF encode(sha256(convert_to(up23, 'UTF8')), 'hex') <> c_up23 THEN RAISE EXCEPTION 'E7_23_UP23_BYTES_MISMATCH'; END IF;
  IF current_user::text <> (SELECT pg_catalog.pg_get_userbyid(nspowner)::text FROM pg_catalog.pg_namespace WHERE nspname = 'booking') THEN RAISE EXCEPTION 'E7_23_NOT_SCHEMA_OWNER'; END IF;
  IF to_regclass('booking_migrations.applied') IS NULL THEN RAISE EXCEPTION 'E7_23_NO_TRACKING_TABLE'; END IF;
